# Step 6: delayed review-request email. Adds sendReviewRequestEmail
# to email.ts and a new cron route (triggered externally via
# cron-job.org, same auth pattern as send-notifications) that finds
# un-invited, sufficiently-aged, non-expired review tokens and emails them.

New-Item -ItemType Directory -Force -Path "src\app\api\cron\send-review-requests" | Out-Null

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\lib\email.ts"), $bytes)
Write-Host "UPDATED: src\lib\email.ts" -ForegroundColor Green

$bytes = [System.Convert]::FromBase64String("")
[System.IO.File]::WriteAllBytes((Join-Path (Get-Location) "src\app\api\cron\send-review-requests\route.ts"), $bytes)
Write-Host "NEW: src\app\api\cron\send-review-requests\route.ts" -ForegroundColor Green

Write-Host "`nBoth files written." -ForegroundColor Cyan
Write-Host "Now run: npx tsc --noEmit" -ForegroundColor Cyan